function getLerpedColor(arr, f) {
	f *= arr.length;
	const c1i = ~~(f);
	const c2i = (c1i + 1) % arr.length;
	const c1 = color(arr[c1i]);
	const c2 = color(arr[c2i]);
	return lerpColor(c1, c2, fract(f));
}

function adjColorSaturation(clr, f = 1) {
	if (typeof clr === 'string' || clr instanceof String || Number.isInteger(clr)) clr = color(clr);

	const br = brightness(window.color(clr));
	return color(
		constrain(lerp(br, red(window.color(clr)), f), 0, 255),
		constrain(lerp(br, green(window.color(clr)), f), 0, 255),
		constrain(lerp(br, blue(window.color(clr)), f), 0, 255),
	)
}

function adjColorBrightness(clr, f = 1) {
	if (typeof clr === 'string' || clr instanceof String || Number.isInteger(clr)) clr = color(clr);

	return color(
		constrain(red(window.color(clr)) * f, 0, 255),
		constrain(green(window.color(clr)) * f, 0, 255),
		constrain(blue(window.color(clr)) * f, 0, 255)
	)
}

